package com.nexttv;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;import java.util.*;

/** UI bounds and public Activity diagnostics; works against actual minified Release. */
public class BrowserLayoutInstrumentation extends Instrumentation {
 private Activity activity;private android.content.SharedPreferences prefs;private Map<String,?> saved;private int passed;private String tag="normal";
 @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null)tag=b.getString("shotTag","normal");start();}
 private AccessibilityNodeInfo root(){AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();if(n!=null)n.refresh();return n;}
 private String text(AccessibilityNodeInfo n){return FreshAccessibilityNodes.text(n);}
 private AccessibilityNodeInfo find(String s,AccessibilityNodeInfo n){if(n==null||!n.refresh())return null;if(s.contentEquals(n.getText()==null?"":n.getText()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo a=find(s,n.getChild(i));if(a!=null)return a;}return null;}
 private void await(String label,java.util.concurrent.Callable<Boolean> f)throws Exception{long until=SystemClock.uptimeMillis()+45000;while(SystemClock.uptimeMillis()<until){if(f.call())return;SystemClock.sleep(80);}throw new IllegalStateException(label+" UI="+text(root()));}
 private String dump(){java.io.StringWriter s=new java.io.StringWriter();runOnMainSync(()->activity.dump("",null,new java.io.PrintWriter(s),null));return s.toString();}
 private org.json.JSONObject state()throws Exception{java.util.regex.Matcher m=java.util.regex.Pattern.compile("NextTVBrowser (\\{[^\\n]+\\})").matcher(dump());if(!m.find())return new org.json.JSONObject();return new org.json.JSONObject(m.group(1));}
 private void click(String s)throws Exception{await(s,()->find(s,root())!=null);AccessibilityNodeInfo n=find(s,root());while(!n.isClickable())n=n.getParent();if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new IllegalStateException("Click "+s);waitForIdleSync();}
 private void key(int k){sendKeyDownUpSync(k);waitForIdleSync();SystemClock.sleep(300);}
 private Rect rect(AccessibilityNodeInfo n){Rect r=new Rect();n.getBoundsInScreen(r);return r;}
 private Rect row(AccessibilityNodeInfo n){while(n!=null&&!n.isClickable())n=n.getParent();if(n==null)throw new IllegalStateException("Missing clickable row");return rect(n);}
 private List<Rect> headings(){float density=getTargetContext().getResources().getDisplayMetrics().density;List<Rect> out=new ArrayList<>();collectHeadings(root(),out,40*density);java.util.Collections.sort(out,new java.util.Comparator<Rect>(){public int compare(Rect a,Rect b){return Integer.compare(a.left,b.left);}});return out;}
 private void collectHeadings(AccessibilityNodeInfo n,List<Rect> out,float ceiling){if(n==null||!n.refresh())return;Rect r=rect(n);if(n.getText()!=null&&r.top>=0&&r.top<ceiling&&!n.getText().toString().isEmpty())out.add(r);for(int i=0;i<n.getChildCount();i++)collectHeadings(n.getChild(i),out,ceiling);}
 private void times(AccessibilityNodeInfo n,List<Rect> rows,int minX){if(n==null||!n.refresh())return;if(n.getText()!=null&&n.getText().toString().matches("\\d{2}:\\d{2}")&&rect(n).left>=minX){Rect r=row(n);boolean exists=false;for(Rect item:rows)if(item.equals(r)){exists=true;break;}if(!exists)rows.add(r);}for(int i=0;i<n.getChildCount();i++)times(n.getChild(i),rows,minX);}
 private Rect viewport(AccessibilityNodeInfo n){while(n!=null&&!n.isScrollable()&&n.getCollectionInfo()==null)n=n.getParent();if(n==null)throw new IllegalStateException("Missing list viewport");return rect(n);}
 private void readable(AccessibilityNodeInfo n,float sp){if(n==null)throw new IllegalStateException("Missing full label");android.graphics.Paint p=new android.graphics.Paint();p.setTypeface(android.graphics.Typeface.SANS_SERIF);p.setTextSize(sp*getTargetContext().getResources().getDisplayMetrics().scaledDensity);float wanted=p.measureText(n.getText().toString());if(rect(n).width()+2<wanted)throw new IllegalStateException("Text clipped "+n.getText()+" width="+rect(n).width()+" needed="+wanted);}
 private void readableDates(AccessibilityNodeInfo n){if(n==null||!n.refresh())return;if(n.getText()!=null&&n.getText().toString().matches("\\d{2}-\\d{2}"))readable(n,12);for(int i=0;i<n.getChildCount();i++)readableDates(n.getChild(i));}
 protected void pass(String s){passed++;Bundle b=new Bundle();b.putString("stream","PASS "+s+"\n");sendStatus(0,b);}
 private void shot(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new IllegalStateException("No screenshot");android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"nexttv-1.3.37-browser-"+tag+"-"+name+".png");v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"image/png");v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(java.io.OutputStream stream=getTargetContext().getContentResolver().openOutputStream(uri)){b.compress(Bitmap.CompressFormat.PNG,100,stream);}b.recycle();}
 private void restore(){if(activity!=null)runOnMainSync(()->activity.finish());if(saved==null)return;android.content.SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> i:saved.entrySet()){Object v=i.getValue();String k=i.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);}e.commit();}
 @Override public void onStart(){int result=Activity.RESULT_OK;String report="";try{
  prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("previews",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).putBoolean("show_channel_logos",true).commit();activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));click("CCTV1综合");await("actual video frame",()->dump().matches("(?s).*firstFrameMs=[1-9][0-9]*.*"));key(KeyEvent.KEYCODE_ENTER);await("channel browser",()->state().optString("region").equals("channels"));SystemClock.sleep(500);
  Rect channel=row(find("CCTV1综合",root()));List<Rect> h=headings();if(h.size()!=1)throw new IllegalStateException("Expected channel heading "+h);Rect channelTitle=h.get(0);float density=getTargetContext().getResources().getDisplayMetrics().density;Bitmap capture=getUiAutomation().takeScreenshot();int screen=capture.getWidth();capture.recycle();float share=channel.width()/(screen-32*density);if(share<.26f||share>.36f)throw new IllegalStateException("Channel width unreadable "+share+" "+channel);int channelGap=viewport(find("CCTV1综合",root())).top-channelTitle.bottom;shot("channels");pass("adaptive channel row share="+share+" headingGap="+channelGap+"px");
  key(KeyEvent.KEYCODE_DPAD_LEFT);await("groups",()->state().optString("region").equals("groups"));h=headings();if(h.size()!=2)throw new IllegalStateException("Expected group/channel headings "+h);Rect firstGroup=row(find("全部频道",root()));int groupGap=viewport(find("全部频道",root())).top-h.get(0).bottom;int shiftedChannelGap=viewport(find("CCTV1综合",root())).top-h.get(1).bottom;if(Math.abs(groupGap-shiftedChannelGap)>2*density||Math.abs(groupGap-channelGap)>2*density)throw new IllegalStateException("Header gaps differ group="+groupGap+" channel="+shiftedChannelGap+" single="+channelGap);readable(find("全部频道",root()),14);shot("groups");pass("group and channel header-to-content gaps match="+groupGap+"px");
  key(KeyEvent.KEYCODE_DPAD_RIGHT);await("groups close on Right",()->state().optString("pane").equals("channels"));Rect original=row(find("CCTV1综合",root()));int listIndex=state().getInt("channelFirst"),offset=state().getInt("channelOffset");key(KeyEvent.KEYCODE_DPAD_RIGHT);await("programme pane",()->state().optString("pane").equals("epg"));SystemClock.sleep(700);Rect after=row(find("CCTV1综合",root()));if(!original.equals(after)||listIndex!=state().getInt("channelFirst")||offset!=state().getInt("channelOffset"))throw new IllegalStateException("Channel pane moved opening EPG "+original+" → "+after);h=headings();if(h.size()!=3)throw new IllegalStateException("Expected channel/programme/date headings "+h);List<Rect> programmes=new ArrayList<>();times(root(),programmes,h.get(1).left);java.util.Collections.sort(programmes,new java.util.Comparator<Rect>(){public int compare(Rect a,Rect b){return Integer.compare(a.top,b.top);}});if(programmes.size()<2)throw new IllegalStateException("No programme rows");Rect epgViewport=null;java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(root());while(!q.isEmpty()){AccessibilityNodeInfo n=q.removeFirst();Rect r=rect(n);if((n.isScrollable()||n.getCollectionInfo()!=null)&&r.left<=h.get(1).centerX()&&r.right>=h.get(1).centerX()&&r.left<h.get(2).left){epgViewport=r;break;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}if(epgViewport==null)throw new IllegalStateException("No programme viewport");int epgGap=epgViewport.top-h.get(1).bottom;final Rect bounds=epgViewport;for(int i=programmes.size()-1;i>=0;i--){Rect r=programmes.get(i);if(r.top<bounds.top||r.bottom>bounds.bottom||r.height()<48*density-2)programmes.remove(i);}if(programmes.size()<2)throw new IllegalStateException("Not enough fully visible programme rows");if(Math.abs(groupGap-epgGap)>2*density)throw new IllegalStateException("Programme header gap differs "+epgGap+" vs "+groupGap);for(int i=1;i<programmes.size();i++){int space=programmes.get(i).top-programmes.get(i-1).bottom;if(Math.abs(space-3*density)>2)throw new IllegalStateException("Programme row spacing="+space);}if(h.get(2).right>screen*.79f)throw new IllegalStateException("Guide fills screen "+h);readableDates(root());shot("programmes");pass("EPG keeps channel geometry/scroll, matching header gap="+epgGap+"px and 3dp programme spacing");
  key(KeyEvent.KEYCODE_ESCAPE);await("EPG collapses to channels on one Back",()->state().optString("pane").equals("channels"));key(KeyEvent.KEYCODE_ESCAPE);await("second Back closes browser",()->!dump().contains("NextTVBrowser"));pass("Back collapses EPG one layer at a time, then dismisses browser");report="Browser layout: "+passed+" groups passed\n";
 }catch(Throwable t){result=Activity.RESULT_CANCELED;report=android.util.Log.getStackTraceString(t)+"\n"+dump();try{shot("failure");}catch(Exception ignored){}}finally{restore();}Bundle b=new Bundle();b.putString("stream",report);finish(result,b);}
}
